PREFIX : <https://w3id.org/rastro/proveedores#>
SELECT (SUM(?amt) AS ?total) WHERE {
  ?c a :Contract ; :supplier ?s ; :amount ?amt .
  ?s :group ?g . ?g :name ?gn .
  FILTER(CONTAINS(UCASE(?gn), "LEIDOS"))
}

PREFIX : <https://w3id.org/rastro/proveedores#>
SELECT DISTINCT ?an WHERE {
  { SELECT ?ag (SUM(?a1) AS ?total) WHERE {
      ?c1 a :Contract ; :agency ?ag ; :amount ?a1 .
    } GROUP BY ?ag }
  { SELECT ?ag ?g (SUM(?a2) AS ?gtotal) WHERE {
      ?c2 a :Contract ; :agency ?ag ; :amount ?a2 ; :supplier ?s .
      ?s :group ?g .
    } GROUP BY ?ag ?g }
  ?ag :name ?an .
  FILTER(?gtotal * 3 > ?total)
}

PREFIX : <https://w3id.org/rastro/proveedores#>
SELECT (COUNT(DISTINCT ?uei) AS ?n) WHERE {
  ?s a :Supplier ; :uei ?uei ; :watchlistMatch ?e .
  ?e :entryType ?t . FILTER(STR(?t) = "Entity")
}

PREFIX : <https://w3id.org/rastro/proveedores#>
SELECT (SUM(?amt) AS ?total) WHERE {
  { SELECT DISTINCT ?c ?amt WHERE {
      ?c a :Contract ; :agency ?ag ; :amount ?amt ; :supplier ?s .
      ?ag :name ?an . FILTER(STR(?an) = "Department of Defense")
      {
        ?s a :ForeignParentSupplier .
      } UNION {
        ?s :watchlistMatch ?e .
        ?e :entryType ?t . FILTER(STR(?t) = "Entity")
      } UNION {
        ?s :group ?g . ?g :watchlistMatch ?e2 .
        ?e2 :entryType ?t2 . FILTER(STR(?t2) = "Entity")
      }
  } }
}
